steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -d '{
    "query": "{
      issue(identifier: \"WEB-7\") {
        id
        identifier
        title
        comments(first: 50) {
          nodes {
            id
            body
            createdAt
            resolvedAt
            user {
              id
              name
            }
            replies(first: 50) {
              nodes {
                id
                body
                createdAt
                resolvedAt
                user {
                  id
                  name
                }
              }
            }
          }
        }
      }
    }
  }'

curl -s https://api.linear.app/graphql -H "Content-Type: application/json" --data @- <<'EOF'
{"query":"{ issue(identifier: \"WEB-7\") { id identifier title comments(first: 50) { nodes { id body createdAt resolvedAt user { id name } replies(first: 50) { nodes { id body createdAt resolvedAt user { id name } } } } } }"}
EOF
